// ============================================
// ESTADOS DE WHATSAPP - CONFIGURA AQUI
// ============================================
// Agrega, quita o modifica los estados que quieras publicar.
// El bot rotara entre ellos automaticamente.
// Puedes poner emojis, saltos de linea, etc.
// ============================================

const estados = [
  // === TESTIMONIOS / PRUEBA SOCIAL ===
  '"Desde que entre a la comunidad, mi vida cambio completamente" - Testimonio real de una de nuestras alumnas \n\nTu tambien puedes lograrlo. Escríbeme y te cuento como',

  'Otro mes, otra transformacion increible de nuestros alumnos \n\nLas mentorias funcionan porque no te dejamos solo en el proceso \n\nQuieres saber mas? Escribeme',

  // === VALOR / TIPS ===
  'El secreto que nadie te dice: no necesitas tenerlo todo claro para empezar. Solo necesitas dar el primer paso \n\nYo puedo ayudarte a darlo',

  'Error #1 que veo en personas que quieren crecer: intentar hacerlo solos \n\nPor eso creamos esta comunidad, para que no tengas que pasar por eso',

  // === LLAMADO A LA ACCION ===
  'Lugares limitados para la mentoria de este mes \n\nSi llevas tiempo pensandolo, este es tu momento \n\nEscribeme "INFO" y te cuento todo',

  'Que pasaria si en 30 dias estuvieras en un lugar completamente diferente? \n\nYo te ayudo a llegar ahi. Escribeme',

  // === LIFESTYLE / CERCANIA ===
  'Preparando contenido nuevo para la comunidad \n\nSe vienen cosas increibles esta semana',

  'Live en unos minutos! No te lo pierdas \n\nHoy hablamos de [tema del dia]',

  // === URGENCIA / PROMO ===
  'Solo por hoy tenemos algo especial para ti \n\nEscribeme "PROMO" y te cuento',

  'Ultimos dias para aprovechar el precio actual \n\nDespues sube. Escribeme y no te quedes fuera'
];

// Seleccionar estado basado en la hora del dia y rotacion
const hora = new Date().getHours();
const dia = new Date().getDay();
const indice = (dia * 3 + Math.floor(hora / 8)) % estados.length;

const estadoSeleccionado = estados[indice];

return [{
  json: {
    texto: estadoSeleccionado,
    hora: hora,
    dia: dia,
    indice: indice
  }
}];
